from itertools import combinations

def solve_partition():
    # We need to partition {1, 2, ..., 21} into 3 subsets each summing to 77
    target = 77
    numbers = list(range(1, 22))

    # Use backtracking with constraint propagation
    # assignment[i] = which subset (0, 1, or 2) number i+1 belongs to
    assignment = [-1] * 21
    subset_sums = [0, 0, 0]

    def backtrack(idx):
        if idx == 21:
            return all(s == target for s in subset_sums)

        num = idx + 1  # The actual number (1-indexed)

        for subset in range(3):
            if subset_sums[subset] + num <= target:
                assignment[idx] = subset
                subset_sums[subset] += num

                if backtrack(idx + 1):
                    return True

                subset_sums[subset] -= num
                assignment[idx] = -1

        return False

    if backtrack(0):
        return assignment
    return None

result = solve_partition()
print("Result:", result)
if result:
    # Verify
    subsets = [[], [], []]
